    public sealed class GangCashierOrder : ExtensibleData
    {
        public string Id,Model;public List<int> Basket=new List<int>(),Route=new List<int>();public int Scanned;
        public bool Matches(GangCashierOptions c)=>c?.Valid==true && !string.IsNullOrWhiteSpace(Id) && Id.Length<=80 && c.Customers.Contains(Model,StringComparer.OrdinalIgnoreCase) && Basket!=null && Basket.Count>=2 && Basket.Count<=7 && Basket.All(i=>i>=0 && i<c.Products.Count) && Scanned>=0 && Scanned<=Basket.Count && Route!=null && Route.Count>=2 && Route.Count<=4 && Route.All(i=>i>=0 && i<c.Shelves.Count) && Route.Distinct().Count()==Route.Count;
    }
    public sealed class GangCashierProgress : ExtensibleData
    {
        public int Elapsed;public bool Faulted;
        [JsonIgnore] public bool Valid=>Elapsed>=0 && Elapsed<=1800000;
    }
    public sealed class GangCashierAttempt : ExtensibleData
    {
        public string Id,Gang;public GangTurfDefinition Area;public GangCashierOptions Options;public GangCashierProgress Progress=new GangCashierProgress();public int Served;public GangCashierOrder Customer;
        [JsonIgnore] public bool Failed=>Progress?.Valid!=true || Options?.Valid!=true || Progress.Faulted || Progress.Elapsed>=Options.SecondsLimit*1000;
        [JsonIgnore] public bool Ready=>Options?.Valid==true && Served==Options.Goal && Customer==null && !Failed;
        [JsonIgnore] public bool Valid=>!string.IsNullOrWhiteSpace(Id) && Id.Length<=80 && !GangLoyaltyRules.Unaffiliated(Gang) && Gang.Length<=100 && Area?.Valid==true && Area.Id==15 && Options?.Valid==true && Progress?.Valid==true && Served>=0 && Served<=Options.Goal && (Customer==null || Served<Options.Goal && Customer.Matches(Options)) && (Served<Options.Goal || !Failed);
    }
    public sealed class GangCashierAccount : ExtensibleData
    {public string Gang;public int Area=15;public long Completed,Customers,Earned;[JsonIgnore] public bool Valid=>!GangLoyaltyRules.Unaffiliated(Gang) && Gang.Length<=100 && Area==15 && Completed>0 && Customers>=Completed && Earned>=Customers;}
    public sealed class GangCashierData : ExtensibleData
    {
        public GangCashierAttempt Pending;public List<GangCashierAccount> Accounts=new List<GangCashierAccount>();public List<string> Receipts=new List<string>();
        [JsonIgnore] public bool Valid=>(Pending==null || Pending.Valid) && Accounts!=null && Accounts.Count<=640 && Accounts.All(a=>a?.Valid==true) && Accounts.Select(a=>a.Gang).Distinct(StringComparer.OrdinalIgnoreCase).Count()==Accounts.Count && Receipts!=null && Receipts.Count<=256 && Receipts.All(r=>!string.IsNullOrWhiteSpace(r) && r.Length<=120) && Receipts.Distinct().Count()==Receipts.Count;
    }
    public static class GangCashierRules
    {public static bool AtTill(bool safe,bool foot,bool ownCustomer,float playerDistance,float customerDistance)=>safe && foot && ownCustomer && GangPresenceRules.Finite(playerDistance) && playerDistance>=0 && playerDistance<=2.5f && GangPresenceRules.Finite(customerDistance) && customerDistance>=0 && customerDistance<=.65f;}
    public sealed class GangCashierClock
    {
        int last;readonly int limit;public GangCashierProgress Progress{get;}
        public GangCashierClock(int now,int limit,GangCashierProgress p){last=now;this.limit=limit;Progress=JsonConvert.DeserializeObject<GangCashierProgress>(JsonConvert.SerializeObject(p));}
        public void Tick(int now,bool working){uint delta=unchecked((uint)(now-last));last=now;if(!working || delta>2000)return;Progress.Elapsed=(int)Math.Min(limit,(long)Progress.Elapsed+delta);}
    }
    public static class GangCashierTransactions
    {
        static T Copy<T>(T v)=>JsonConvert.DeserializeObject<T>(JsonConvert.SerializeObject(v));static bool Id(string id)=>!string.IsNullOrWhiteSpace(id) && id.Length<=80;
        public static bool Blocked(WalletData w)=>w?.GangCashier!=null && (!w.GangCashier.Valid || w.GangCashier.Pending!=null);
        public static bool OtherFree(WalletData w)=>w!=null && !GangBmxTransactions.Blocked(w) && !GangPierTransactions.Blocked(w) && !GangOffshoreTransactions.Blocked(w) && !GangDockTransactions.Blocked(w) && !GangChauffeurTransactions.Blocked(w) && !GangTheatreTransactions.Blocked(w) && !GangMowingTransactions.Blocked(w) && !GangPopUpTransactions.Blocked(w) && !GangMedicalTransactions.Blocked(w) && !GangCashRunTransactions.Blocked(w) && !GangTowTransactions.Blocked(w) && !GangMechanicTransactions.Blocked(w) && !GangPromotionTransactions.Blocked(w) && (w.GangBulk==null || w.GangBulk.Valid && w.GangBulk.Pending==null) && (w.GangRaid==null || w.GangRaid.Valid && w.GangRaid.Pending==null) && (w.GangBusiness==null || w.GangBusiness.Valid && w.GangBusiness.Supply==null);
        public static GangCashierAccount Account(GangCashierData b,string gang)=>b?.Valid==true?b.Accounts.FirstOrDefault(a=>GangCrewRules.SameGang(a.Gang,gang)):null;
        static bool Apply(WalletData w,string receipt,Func<GangCashierData,bool> mutate,Action save,out bool changed)
        {changed=false;if(w==null || w.Bank<0 || save==null || w.GangCashier!=null && !w.GangCashier.Valid)return false;var old=w.GangCashier;if(old?.Receipts.Contains(receipt)==true)return true;var b=old==null?new GangCashierData():Copy(old);if(!mutate(b) || !b.Valid)return false;b.Receipts.Add(receipt);if(b.Receipts.Count>256)b.Receipts.RemoveAt(0);try{w.GangCashier=b;save();changed=true;return true;}catch{w.GangCashier=old;throw;}}
        static bool Owns(GangState s,GangTurfDefinition area,GangCashierAttempt p)=>p!=null && area?.Id==15 && GangBusinessTransactions.Owns(s,area) && GangCrewRules.SameGang(s.Gang,p.Gang);
        public static bool Begin(WalletData w,GangState s,GangTurfDefinition area,GangCashierOptions c,string id,Action save,out bool changed)
        {changed=false;if(!Id(id) || area?.Id!=15 || !GangBusinessTransactions.Owns(s,area) || c?.Valid!=true || !OtherFree(w))return false;return Apply(w,id+":till-begin",b=>{if(b.Pending!=null)return false;var a=Account(b,s.Gang);if(a?.Completed==long.MaxValue || a==null && b.Accounts.Count>=640)return false;b.Pending=new GangCashierAttempt{Id=id,Gang=s.Gang,Area=Copy(area),Options=Copy(c)};return true;},save,out changed);}
        public static bool Update(WalletData w,GangState s,GangTurfDefinition area,string id,GangCashierProgress progress,Action save,out bool changed)
        {changed=false;var p=w?.GangCashier?.Pending;if(!Id(id) || p?.Id!=id || w.GangCashier.Valid!=true || p.Ready || !Owns(s,area,p) || !OtherFree(w) || progress?.Valid!=true || progress.Elapsed<p.Progress.Elapsed || progress.Elapsed>p.Options.SecondsLimit*1000 || p.Progress.Faulted && !progress.Faulted)return false;return Apply(w,Guid.NewGuid().ToString("N")+":till-sample",b=>{b.Pending.Progress.Elapsed=progress.Elapsed;b.Pending.Progress.Faulted=progress.Faulted;return true;},save,out changed);}
        public static bool Customer(WalletData w,GangState s,GangTurfDefinition area,string id,GangCashierOrder order,Action save,out bool changed)
        {changed=false;if(!Id(id) || !Owns(s,area,w?.GangCashier?.Pending) || !OtherFree(w))return false;return Apply(w,order?.Id+":till-order",b=>{var p=b.Pending;if(p.Id!=id || p.Failed || p.Ready || p.Customer!=null || order?.Matches(p.Options)!=true || order.Scanned!=0)return false;p.Customer=Copy(order);return true;},save,out changed);}
        public static bool Scan(WalletData w,GangState s,GangTurfDefinition area,string id,string customer,int index,Action save,out bool changed)
        {changed=false;if(!Id(id) || !Id(customer) || index<0 || index>=7 || !Owns(s,area,w?.GangCashier?.Pending) || !OtherFree(w))return false;return Apply(w,customer+":till-scan:"+index,b=>{var p=b.Pending;if(p.Id!=id || p.Failed || p.Customer?.Id!=customer || p.Customer.Scanned!=index || index>=p.Customer.Basket.Count)return false;p.Customer.Scanned++;return true;},save,out changed);}
        public static bool Pay(WalletData w,GangState s,GangTurfDefinition area,string id,string customer,Action save,out bool changed)
        {changed=false;if(!Id(id) || !Id(customer) || !Owns(s,area,w?.GangCashier?.Pending) || !OtherFree(w))return false;return Apply(w,customer+":till-pay",b=>{var p=b.Pending;if(p.Id!=id || p.Failed || p.Customer?.Id!=customer || p.Customer.Scanned!=p.Customer.Basket.Count)return false;p.Customer=null;p.Served++;return true;},save,out changed);}
        public static bool Cancel(WalletData w,string id,Action save,out bool changed){changed=false;if(!Id(id))return false;return Apply(w,id+":till-cancel",b=>{if(b.Pending?.Id!=id)return false;b.Pending=null;return true;},save,out changed);}
        // Native protagonist cash is external GTA state; session rollback follows DeliveryPayments.
        public static bool Complete(WalletData w,GangState s,GangTurfDefinition area,string id,Func<int> cash,Action<int> setCash,Action save,out bool changed)
        {
            changed=false;if(!Id(id) || w==null || w.Bank<0 || cash==null || setCash==null || save==null || w.GangCashier?.Valid!=true || area?.Id!=15 || !GangBusinessTransactions.Owns(s,area) || !OtherFree(w))return false;
            string receipt=id+":till-complete";var old=w.GangCashier;if(old.Receipts.Contains(receipt))return true;var b=Copy(old);var p=b.Pending;if(p?.Id!=id || !p.Ready || !Owns(s,area,p))return false;
            int amount=p.Served*p.Options.Wage,before=cash();if(before<0 || before>int.MaxValue-amount)return false;var a=Account(b,p.Gang);if(a==null){if(b.Accounts.Count>=640)return false;a=new GangCashierAccount{Gang=p.Gang};b.Accounts.Add(a);}if(a.Completed==long.MaxValue || a.Customers>long.MaxValue-p.Served || a.Earned>long.MaxValue-amount)return false;
            a.Completed++;a.Customers+=p.Served;a.Earned+=amount;b.Pending=null;b.Receipts.Add(receipt);if(b.Receipts.Count>256)b.Receipts.RemoveAt(0);if(!b.Valid)return false;
            try{w.GangCashier=b;setCash(before+amount);save();changed=true;return true;}catch{w.GangCashier=old;setCash(before);throw;}
        }
    }
}
